    "Card"
  ],
  "notifications": {
    "report_emails": [
      "doctor@example.com"
    ],
    "report_whatsapp_numbers": [
      "919000000001"
    ],
    "admin_email": "alerts@example.com"
  },
  "schedules": {
    "reminder_cron": "0 18 * * *",
    "report_cron": "0 21 * * *",
    "same_day_reminder_cron": "0 8-19 * * *"
  },
  "reminders": {
    "appointment_day_before": true,
    "follow_up": true,
    "same_day_hours_before": 2
  },
  "whatsapp": {
