// ---------------------------------------------------------------------------
// dates.js — timezone-safe date/time helpers.
// All dates in the Sheet are plain text "YYYY-MM-DD", times are "HH:MM" (24h).
// This file is compiled into n8n Code nodes by scripts/build.js, so it must be
// plain JavaScript with no imports (the strip blocks are removed at build time).
// ---------------------------------------------------------------------------

const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function pad2(n) {
  return String(n).padStart(2, '0');
}

/** Today's date (YYYY-MM-DD) in the clinic's timezone. */
function todayIn(tz, now) {
  const d = now instanceof Date ? now : new Date();
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit',
  }).format(d);
}

/** Current time (HH:MM, 24h) in the clinic's timezone. */
function timeIn(tz, now) {
  const d = now instanceof Date ? now : new Date();
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz, hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(d);
  const h = parts.find((p) => p.type === 'hour').value;
  const m = parts.find((p) => p.type === 'minute').value;
  return pad2(h) + ':' + pad2(m);
}

function isIsoDate(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const [y, m, d] = s.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}

/** Add n calendar days to an ISO date string. */
function addDays(iso, n) {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

/** Whole days from iso a to iso b (b - a). */
function daysBetween(a, b) {
  const ta = Date.parse(a + 'T00:00:00Z');
  const tb = Date.parse(b + 'T00:00:00Z');
  return Math.round((tb - ta) / 86400000);
}

function weekdayName(iso) {
  return WEEKDAYS[new Date(iso + 'T00:00:00Z').getUTCDay()];
}

/**
 * Normalise whatever a form / Google Sheet gives us into YYYY-MM-DD.
 * Handles: "2026-11-18", "2026-11-18T00:00:00.000Z", "18/11/2026", "18-11-2026",
 * "11/18/2026" (only when order === 'MDY'), and Google serial numbers (45980).
 * Returns '' when it cannot be parsed.
 */
function normalizeDate(value, order) {
  if (value === null || value === undefined || value === '') return '';
  if (typeof value === 'number' && value > 20000 && value < 80000) {
    // Google Sheets / Excel serial date (days since 1899-12-30)
    return new Date(Date.UTC(1899, 11, 30) + value * 86400000).toISOString().slice(0, 10);
  }
  const s = String(value).trim();
  const iso = s.slice(0, 10);
  if (isIsoDate(iso)) return iso;
  const m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);
  if (m) {
    const a = Number(m[1]);
    const b = Number(m[2]);
    const y = m[3];
    const [day, month] = order === 'MDY' ? [b, a] : [a, b];
    const out = y + '-' + pad2(month) + '-' + pad2(day);
    return isIsoDate(out) ? out : '';
  }
  return '';
}

/**
 * Normalise a time into HH:MM (24h). Accepts "9:5", "09:05", "17:30",
 * "5:30 PM", "5 pm", "17:30:00", and Sheets day-fractions (0.729166 = 17:30).
 */
function normalizeTime(value) {
  if (value === null || value === undefined || value === '') return '';
  if (typeof value === 'number' && value >= 0 && value < 1) {
    const total = Math.round(value * 24 * 60);
    return pad2(Math.floor(total / 60)) + ':' + pad2(total % 60);
  }
  const s = String(value).trim().toLowerCase();
  const m = s.match(/^(\d{1,2})(?:[:.](\d{1,2}))?(?::\d{2})?\s*(am|pm)?$/);
  if (!m) return '';
  let h = Number(m[1]);
  const min = Number(m[2] || 0);
  if (m[3] === 'pm' && h < 12) h += 12;
  if (m[3] === 'am' && h === 12) h = 0;
  if (h > 23 || min > 59) return '';
  return pad2(h) + ':' + pad2(min);
}

function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function fromMinutes(total) {
  return pad2(Math.floor(total / 60)) + ':' + pad2(total % 60);
}

/** "2026-11-18" -> "18 Nov 2026" */
function displayDate(iso) {
  if (!isIsoDate(iso)) return iso || '';
  const [y, m, d] = iso.split('-').map(Number);
  return d + ' ' + MONTHS[m - 1] + ' ' + y;
}

/** "17:30" -> "5:30 PM" */
function displayTime(hhmm) {
  const t = normalizeTime(hhmm);
  if (!t) return hhmm || '';
  let [h, m] = t.split(':').map(Number);
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12 === 0 ? 12 : h % 12;
  return h + ':' + pad2(m) + ' ' + ampm;
}

// ---------------------------------------------------------------------------
// phone.js — WhatsApp number cleanup. Output: digits only, with country code,
// no "+" or spaces (e.g. 919876543210) — the format the WhatsApp API expects.
// ---------------------------------------------------------------------------

function normalizePhone(raw, countryCode, localLength) {
  const cc = String(countryCode || '91');
  const len = Number(localLength || 10);
  let d = String(raw === undefined || raw === null ? '' : raw).replace(/\D/g, '');
  if (d.startsWith('00')) d = d.slice(2); // 0091... international prefix
  if (d.length === len + 1 && d.startsWith('0')) d = d.slice(1); // 09876543210 trunk prefix
  if (d.length === len) d = cc + d;
  return d;
}

/**
 * A number is valid when it is 8-15 digits (E.164) and, if it uses the clinic's
 * own country code, has exactly the local length after it.
 */
function isValidPhone(phone, countryCode, localLength) {
  const cc = String(countryCode || '91');
  const len = Number(localLength || 10);
  if (!/^\d{8,15}$/.test(phone)) return false;
  if (phone.startsWith(cc) && phone.length !== cc.length + len) return false;
  if (!phone.startsWith(cc) && phone.length <= len) return false;
  return true;
}

/** 919876543210 -> 98xxxxx210 — for alerts/emails so full numbers don't leak. */
function maskPhone(phone) {
  const s = String(phone || '');
  if (s.length < 6) return s;
  return s.slice(-10, -8) + 'xxxxx' + s.slice(-3);
}

// ---------------------------------------------------------------------------
// schedule.js — clinic hours, doctor-wise sessions, closed days, holidays.
// Depends on: dates.js
// ---------------------------------------------------------------------------

/**
 * Resolve one doctor's effective schedule. Each doctor in the config can be a
 * plain string ("Dr. Mehta") or an object that overrides the clinic defaults:
 * { name, sessions, closed_weekdays, patients_per_slot, slot_minutes }.
 */
function doctorSchedule(config, doctorName) {
  const s = config.schedule || {};
  const list = (config.doctors || []).map((d) => (typeof d === 'string' ? { name: d } : d));
  const doc = list.find((d) => d.name.toLowerCase() === String(doctorName || '').trim().toLowerCase());
  if (!doc) return null;
  return {
    name: doc.name,
    sessions: doc.sessions || s.sessions || [],
    closed_weekdays: doc.closed_weekdays || s.closed_weekdays || [],
    patients_per_slot: Number(doc.patients_per_slot || s.patients_per_slot || 1),
    slot_minutes: Number(doc.slot_minutes || s.slot_minutes || 15),
  };
}

function doctorNames(config) {
  return (config.doctors || []).map((d) => (typeof d === 'string' ? d : d.name));
}

/** All bookable start times for one doctor, e.g. ['10:00','10:15',...]. */
function slotsForDoctor(config, doctorName) {
  const ds = doctorSchedule(config, doctorName);
  if (!ds) return [];
  const out = [];
  for (const sess of ds.sessions) {
    const start = toMinutes(sess.start);
    const end = toMinutes(sess.end);
    for (let t = start; t + ds.slot_minutes <= end; t += ds.slot_minutes) out.push(fromMinutes(t));
  }
  return out;
}

/** Union of every doctor's slots — used for the booking form's dropdown. */
function allSlots(config) {
  const set = new Set();
  for (const name of doctorNames(config)) for (const t of slotsForDoctor(config, name)) set.add(t);
  return [...set].sort();
}

/** Is the clinic / this doctor open on that date? Returns { open, reason }. */
function isOpenDay(config, doctorName, iso) {
  const ds = doctorSchedule(config, doctorName);
  if (!ds) return { open: false, reason: 'Unknown doctor "' + doctorName + '"' };
  const holidays = (config.schedule && config.schedule.holidays) || [];
  if (holidays.includes(iso)) return { open: false, reason: iso + ' is a clinic holiday' };
  const wd = weekdayName(iso);
  const closed = ds.closed_weekdays.map((w) => String(w).toLowerCase());
  if (closed.includes(wd.toLowerCase()) || closed.includes(wd.slice(0, 3).toLowerCase())) {
    return { open: false, reason: ds.name + ' is not available on ' + wd + 's' };
  }
  return { open: true, reason: '' };
}

/** First open day for the doctor on/after iso (max 30 days ahead). */
function nextOpenDay(config, doctorName, iso) {
  let d = iso;
  for (let i = 0; i < 30; i++) {
    if (isOpenDay(config, doctorName, d).open) return d;
    d = addDays(d, 1);
  }
  return iso;
}

// ---------------------------------------------------------------------------
// sheet.js — the Appointments tab schema and row cleanup.
// Depends on: dates.js
// ---------------------------------------------------------------------------

// Exact header row of the "Appointments" tab (A..O). n8n matches by name —
// never rename these in a client's sheet.
const APPOINTMENT_COLUMNS = [
  'appointment_id', 'patient_name', 'phone', 'doctor', 'appt_date', 'appt_time',
  'visit_type', 'status', 'payment_status', 'amount_paid', 'payment_mode',
  'follow_up_date', 'whatsapp_consent', 'last_reminder_date', 'booked_on',
];

const STATUS = { BOOKED: 'Booked', COMPLETED: 'Completed', NO_SHOW: 'No-show', CANCELLED: 'Cancelled' };

/**
 * Google Sheets can hand back numbers, formatted dates or stray spaces if a
 * receptionist typed into the sheet by hand. Clean every row before using it.
 */
function normalizeRow(raw, config) {
  const order = (config && config.locale && config.locale.sheet_date_order) || 'DMY';
  const r = {};
  for (const col of APPOINTMENT_COLUMNS) {
    const v = raw[col];
    r[col] = v === undefined || v === null ? '' : typeof v === 'string' ? v.trim() : v;
  }
  r.appointment_id = String(r.appointment_id).toUpperCase();
  r.phone = String(r.phone).replace(/\D/g, '');
  r.appt_date = normalizeDate(r.appt_date, order);
  r.appt_time = normalizeTime(r.appt_time);
  r.follow_up_date = normalizeDate(r.follow_up_date, order);
  r.last_reminder_date = normalizeDate(r.last_reminder_date, order);
  r.booked_on = normalizeDate(r.booked_on, order);
  r.amount_paid = r.amount_paid === '' ? '' : Number(r.amount_paid) || 0;
  r.status = canonicalStatus(r.status);
  if (raw.row_number !== undefined) r.row_number = raw.row_number;
  return r;
}

function canonicalStatus(s) {
  const k = String(s || '').toLowerCase().replace(/[\s_-]/g, '');
  if (k === 'booked' || k === '') return STATUS.BOOKED;
  if (k === 'completed' || k === 'done') return STATUS.COMPLETED;
  if (k === 'noshow') return STATUS.NO_SHOW;
  if (k === 'cancelled' || k === 'canceled') return STATUS.CANCELLED;
  return String(s);
}

/** Only rows that actually are appointments (skip blank / half-typed lines). */
function cleanRows(items, config) {
  return items
    .map((r) => normalizeRow(r, config))
    .filter((r) => r.appointment_id && r.appt_date);
}

/** Full 15-column object with '' defaults — what we append to the sheet. */
function toSheetRow(partial) {
  const out = {};
  for (const col of APPOINTMENT_COLUMNS) out[col] = partial[col] === undefined ? '' : partial[col];
  return out;
}

// ---------------------------------------------------------------------------
// booking.js — validate a booking request and check it against the sheet.
// Used by BOTH the reception booking form and the WhatsApp AI assistant, so
// the rules (double booking, closed days, duplicates) are identical everywhere.
// Depends on: dates.js, phone.js, schedule.js, sheet.js
// ---------------------------------------------------------------------------

const ID_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no 0/O/1/I — easy to read out on phone

function newAppointmentId(existingIds, rand) {
  const r = rand || Math.random;
  const taken = existingIds instanceof Set ? existingIds : new Set(existingIds || []);
  for (let attempt = 0; attempt < 20; attempt++) {
    let id = 'APT-';
    for (let i = 0; i < 6; i++) id += ID_ALPHABET[Math.floor(r() * ID_ALPHABET.length)];
    if (!taken.has(id)) return id;
  }
  throw new Error('Could not generate a unique appointment ID');
}

/**
 * Step 1: clean + validate the request on its own (no sheet needed).
 * input: { patient_name, phone, doctor, appt_date, appt_time, visit_type, whatsapp_consent }
 * returns { booking, errors[] }
 */
function cleanBooking(input, config, now) {
  const tz = config.locale.timezone;
  const errors = [];
  const today = todayIn(tz, now);

  const name = String(input.patient_name || '').replace(/\s+/g, ' ').trim();
  if (name.length < 2) errors.push('Patient name is missing.');

  const phone = normalizePhone(input.phone, config.locale.country_code, config.locale.local_phone_length);
  if (!isValidPhone(phone, config.locale.country_code, config.locale.local_phone_length)) {
    errors.push('Phone number "' + (input.phone || '') + '" is not valid. Use a ' + config.locale.local_phone_length + '-digit mobile number.');
  }

  const ds = doctorSchedule(config, input.doctor);
  if (!ds) errors.push('Doctor "' + (input.doctor || '') + '" is not in this clinic\'s list.');
  const doctor = ds ? ds.name : String(input.doctor || '');

  const date = normalizeDate(input.appt_date, config.locale.sheet_date_order);
  if (!date) errors.push('Appointment date is missing or invalid.');

  const time = normalizeTime(input.appt_time);
  if (!time) errors.push('Time slot is missing or invalid.');

  if (date) {
    const ahead = daysBetween(today, date);
    const maxAhead = Number(config.schedule.max_days_ahead || 60);
    if (ahead < 0) errors.push('Date ' + displayDate(date) + ' is in the past.');
    else if (ahead > maxAhead) errors.push('Bookings are open only ' + maxAhead + ' days ahead.');
    if (ds) {
      const open = isOpenDay(config, doctor, date);
      if (!open.open) errors.push(open.reason + '.');
    }
    if (ahead === 0 && time && input.reject_past_times_today && time < timeIn(tz, now)) {
      errors.push('That time has already passed today.');
    }
  }
  if (ds && time && !slotsForDoctor(config, doctor).includes(time)) {
    errors.push(doctor + ' does not have a ' + displayTime(time) + ' slot.');
  }

  const visitTypes = config.visit_types || ['New', 'Follow-up'];
  const visit_type = visitTypes.find((v) => v.toLowerCase() === String(input.visit_type || '').toLowerCase()) || visitTypes[0];
  const consent = /^(yes|y|true|haan|ha)$/i.test(String(input.whatsapp_consent || '').trim()) ? 'Yes' : 'No';

  const booking = toSheetRow({
    patient_name: name,
    phone,
    doctor,
    appt_date: date,
    appt_time: time,
    visit_type,
    status: STATUS.BOOKED,
    payment_status: 'Pending',
    whatsapp_consent: consent,
    booked_on: today,
  });
  return { booking, errors };
}

function activeRows(rows) {
  return rows.filter((r) => r.status !== STATUS.CANCELLED);
}

/** Free slots for a doctor on a date, given existing sheet rows. */
function availableSlots(config, rows, doctor, date, now) {
  const ds = doctorSchedule(config, doctor);
  if (!ds || !isOpenDay(config, ds.name, date).open) return [];
  const tz = config.locale.timezone;
  const today = todayIn(tz, now);
  if (daysBetween(today, date) < 0) return [];
  const nowTime = timeIn(tz, now);
  const counts = {};
  for (const r of activeRows(rows)) {
    if (r.doctor.toLowerCase() === ds.name.toLowerCase() && r.appt_date === date) {
      counts[r.appt_time] = (counts[r.appt_time] || 0) + 1;
    }
  }
  return slotsForDoctor(config, ds.name).filter(
    (t) => (counts[t] || 0) < ds.patients_per_slot && !(date === today && t <= nowTime),
  );
}

/**
 * Step 2: check the cleaned booking against existing rows.
 * Detects: slot full (double booking), same patient already booked with the
 * same doctor that day (double submit). Suggests the next free slots.
 * returns { ok, errors[], suggestions[], booking (with appointment_id) }
 */
function checkBooking(booking, rows, config, now, rand) {
  const errors = [];
  let suggestions = [];
  const ds = doctorSchedule(config, booking.doctor);
  const sameDay = activeRows(rows).filter(
    (r) => r.appt_date === booking.appt_date && r.doctor.toLowerCase() === booking.doctor.toLowerCase(),
  );
  const inSlot = sameDay.filter((r) => r.appt_time === booking.appt_time);
  if (ds && inSlot.length >= ds.patients_per_slot) {
    errors.push(booking.doctor + ' already has ' + inSlot.length + ' booking(s) at ' + displayTime(booking.appt_time) + ' on ' + displayDate(booking.appt_date) + '.');
    // the 3 free slots closest to the requested time (ties go to the later slot)
    const want = toMinutes(booking.appt_time);
    suggestions = availableSlots(config, rows, booking.doctor, booking.appt_date, now)
      .map((t) => ({ t, d: Math.abs(toMinutes(t) - want), later: toMinutes(t) > want ? 0 : 1 }))
      .sort((a, b) => a.d - b.d || a.later - b.later)
      .slice(0, 3)
      .map((x) => x.t)
      .sort();
  }
  const dup = sameDay.find((r) => r.phone === booking.phone && r.status === STATUS.BOOKED);
  if (dup) {
    errors.push('This patient already has appointment ' + dup.appointment_id + ' with ' + dup.doctor + ' at ' + displayTime(dup.appt_time) + ' that day.');
  }
  const ids = new Set(rows.map((r) => r.appointment_id));
  const out = Object.assign({}, booking, { appointment_id: newAppointmentId(ids, rand) });
  return { ok: errors.length === 0, errors, suggestions, booking: out };
}

/** Upcoming (Booked, today or later) appointments for a phone number. */
function upcomingForPhone(rows, phone, today) {
  return rows
    .filter((r) => r.phone === phone && r.status === STATUS.BOOKED && r.appt_date >= today)
    .sort((a, b) => (a.appt_date + a.appt_time).localeCompare(b.appt_date + b.appt_time));
}

// ---------------------------------------------------------------------------
// whatsapp.js — builds WhatsApp Cloud API (Meta Graph API) request bodies.
// Template parameter ORDER comes from the client config, so every client can
// word their approved templates differently without touching code.
// Depends on: dates.js
// ---------------------------------------------------------------------------

/** Every value a template is allowed to use. Keep these free of medical info. */
function templateFields(row, config, extra) {
  const name = String(row.patient_name || '').trim();
  const f = {
    patient_name: name,
    first_name: name.split(' ')[0] || name,
    doctor: row.doctor || '',
    clinic_name: (config.client && config.client.clinic_name) || '',
    clinic_phone: (config.client && config.client.clinic_phone) || '',
    clinic_address: (config.client && config.client.clinic_address) || '',
    appointment_id: row.appointment_id || '',
    appt_date: row.appt_date || '',
    display_date: displayDate(row.appt_date),
    appt_time: row.appt_time || '',
    display_time: displayTime(row.appt_time),
    follow_up_date: row.follow_up_date || '',
    follow_up_display_date: displayDate(row.follow_up_date),
  };
  return Object.assign(f, extra || {});
}

/** Meta rejects params containing newlines, tabs or 4+ consecutive spaces. */
function cleanParam(v) {
  return String(v === undefined || v === null ? '' : v).replace(/[\r\n\t]+/g, ' ').replace(/ {2,}/g, ' ').trim() || '-';
}

/**
 * tpl: { name, language, params: ['patient_name','doctor','display_date','display_time'] }
 */
function buildTemplatePayload(to, tpl, fields) {
  const params = (tpl.params || []).map((key) => {
    if (!(key in fields)) throw new Error('Template "' + tpl.name + '" uses unknown field "' + key + '"');
    return { type: 'text', text: cleanParam(fields[key]) };
  });
  const template = { name: tpl.name, language: { code: tpl.language || 'en' } };
  if (params.length) template.components = [{ type: 'body', parameters: params }];
  return { messaging_product: 'whatsapp', to: String(to), type: 'template', template };
}

/** Free-form text — only allowed within 24h of the patient's last message. */
function buildTextPayload(to, text) {
  return {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: String(to),
    type: 'text',
    text: { preview_url: false, body: String(text).slice(0, 4000) },
  };
}

/** Interpret the HTTP Request node's output (works with "Continue on Fail"). */
function parseSendResult(json) {
  if (json && Array.isArray(json.messages) && json.messages[0] && json.messages[0].id) {
    return { ok: true, message_id: json.messages[0].id, error: '' };
  }
  let err = json && json.error;
  if (err && typeof err === 'object') err = err.message || err.description || JSON.stringify(err);
  return { ok: false, message_id: '', error: String(err || 'Unknown WhatsApp API response') };
}

